import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Popover as AriaPopover,
  composeRenderProps,
  type PopoverProps,
} from "react-aria-components";
import { cn } from "./utils";

function edgeOffset(placement: string | null) {
  switch (placement) {
    case "top":
      return { x: 0, y: 5 };
    case "left":
      return { x: 5, y: 0 };
    case "right":
      return { x: -5, y: 0 };
    default:
      return { x: 0, y: -5 };
  }
}

type StyledPopoverProps = PopoverProps & { "data-slot"?: string };

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: StyledPopoverProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      render={
        props.render ??
        ((domProps, { placement, isExiting }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion || props.shouldSkipAnimation
                ? false
                : { ...edgeOffset(placement), scale: 0.98 }
            }
            animate={
              isExiting && !reduceMotion
                ? { ...edgeOffset(placement), scale: 0.99 }
                : { x: 0, y: 0, scale: 1 }
            }
            transition={{
              duration: isExiting ? 0.14 : 0.2,
              ease: [0.23, 1, 0.32, 1],
            }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] rounded-xl border border-border bg-popover p-5 text-popover-foreground shadow-[var(--shadow-float)] outline-none transition-opacity duration-100 data-[entering]:opacity-0 data-[exiting]:opacity-0 motion-safe:duration-200 motion-safe:data-[exiting]:duration-150 data-[placement=top]:origin-bottom data-[placement=bottom]:origin-top data-[placement=left]:origin-right data-[placement=right]:origin-left",
          className,
        ),
      )}
    />
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { Button, type ButtonProps } from "react-aria-components";

/** React Aria handles presses; Motion supplies the visual feedback. */
export function PressButton({ isDisabled, ...props }: ButtonProps) {
  const reduceMotion = useReducedMotion();

  return (
    <Button
      data-slot="press-button"
      {...props}
      isDisabled={isDisabled}
      render={
        props.render ??
        ((domProps) => (
          <motion.button
            {...(domProps as HTMLMotionProps<"button">)}
            whileTap={reduceMotion || isDisabled ? undefined : { scale: 0.96 }}
            transition={{ duration: 0.14 }}
          />
        ))
      }
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import {
  type Button as AriaButton,
  Select as AriaSelect,
  type SelectProps as AriaSelectProps,
  SelectValue as AriaSelectValue,
  composeRenderProps,
  FieldError,
  Label,
  ListBox,
  ListBoxItem,
  Text,
} from "react-aria-components";
import { Check, ChevronDown } from "reicon-react";
import { cn } from "./utils";
import { Popover } from "./popover";
import { PressButton } from "./press-button";

export interface SelectOption {
  id: string;
  name: string;
  description?: string;
}
export interface SelectProps
  extends Omit<AriaSelectProps<SelectOption>, "children" | "className"> {
  label?: string;
  description?: string;
  options?: SelectOption[];
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaSelectProps<SelectOption>["className"];
  children?: AriaSelectProps<SelectOption>["children"];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export function Select({
  label,
  description,
  options,
  className,
  children,
  value,
  defaultValue,
  onValueChange,
  placeholder = "Select an option",
  ...props
}: SelectProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaSelect
      {...props}
      data-slot="select"
      selectedKey={value ?? props.selectedKey}
      defaultSelectedKey={defaultValue ?? props.defaultSelectedKey}
      onSelectionChange={(key) => {
        props.onSelectionChange?.(key);
        onValueChange?.(key === null ? "" : String(key));
      }}
      placeholder={placeholder}
      className={composeRenderProps(className, (className) =>
        cn("group flex w-full flex-col gap-2", className),
      )}
    >
      {children ??
        (({ isOpen }) => (
          <>
            {label && (
              <Label className="text-[13px] font-medium text-foreground">
                {label}
              </Label>
            )}
            <PressButton
              data-slot="select-trigger"
              className="flex min-h-12 w-full cursor-pointer items-center justify-between gap-3 rounded-lg border border-input bg-card px-3.5 text-start text-sm text-foreground shadow-[var(--shadow-card)] hover:border-primary/45 hover:bg-muted/60 motion-safe:transition-[border-color,background-color,box-shadow] motion-safe:duration-150 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring group-data-[invalid]:border-destructive group-data-[invalid]:ring-3 group-data-[invalid]:ring-destructive/20 data-[disabled]:cursor-default data-[disabled]:bg-muted data-[disabled]:opacity-50"
            >
              <AriaSelectValue
                data-slot="select-value"
                className="min-w-0 flex-1 truncate text-start data-[placeholder]:text-muted-foreground"
              >
                {({ selectedText, isPlaceholder, state }) =>
                  isPlaceholder
                    ? placeholder
                    : (options?.find(
                        (option) => option.id === state.selectedKey,
                      )?.name ?? selectedText)
                }
              </AriaSelectValue>
              <motion.span
                animate={{ rotate: isOpen && !reduceMotion ? 180 : 0 }}
                transition={{ type: "spring", duration: 0.3, bounce: 0 }}
                className="shrink-0 text-muted-foreground"
              >
                <ChevronDown size={16} aria-hidden="true" />
              </motion.span>
            </PressButton>
            {description && (
              <Text
                slot="description"
                className="text-xs leading-5 text-muted-foreground"
              >
                {description}
              </Text>
            )}
            <SelectError />
            <Popover
              data-slot="select-content"
              placement="bottom start"
              offset={7}
              className="w-[var(--trigger-width)] rounded-lg border-0 p-1.5 ring-1 ring-border/70"
            >
              <ListBox
                data-slot="select-list-box"
                items={options ?? []}
                className="grid max-h-64 gap-1 overflow-y-auto outline-none"
              >
                {(option) => (
                  <ListBoxItem
                    data-slot="select-item"
                    id={option.id}
                    textValue={option.name}
                    className="group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm outline-none hover:bg-muted data-[focused]:bg-muted data-[selected]:bg-accent data-[selected]:text-accent-foreground data-[focus-visible]:-outline-offset-2 data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring data-[disabled]:cursor-default data-[disabled]:opacity-50"
                  >
                    <span className="min-w-0">
                      <span className="block font-medium">{option.name}</span>
                      {option.description && (
                        <span className="mt-0.5 block text-xs text-muted-foreground">
                          {option.description}
                        </span>
                      )}
                    </span>
                    <Check
                      size={15}
                      aria-hidden="true"
                      className="shrink-0 opacity-0 group-data-[selected]/item:opacity-100"
                    />
                  </ListBoxItem>
                )}
              </ListBox>
            </Popover>
          </>
        ))}
    </AriaSelect>
  );
}

export function SelectLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="select-label"
      className={cn("text-[13px] font-medium text-foreground", className)}
    />
  );
}

export function SelectTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <PressButton
      {...props}
      data-slot="select-trigger"
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-h-12 w-full cursor-pointer items-center justify-between gap-3 rounded-lg border border-input bg-card px-3.5 text-start text-sm text-foreground shadow-[var(--shadow-card)] hover:border-primary/45 hover:bg-muted/60 motion-safe:transition-[border-color,background-color,box-shadow] motion-safe:duration-150 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring group-data-[invalid]:border-destructive group-data-[invalid]:ring-3 group-data-[invalid]:ring-destructive/20 data-[disabled]:cursor-default data-[disabled]:bg-muted data-[disabled]:opacity-50",
          className,
        ),
      )}
    >
      {children ?? (
        <>
          <SelectValue />
          <ChevronDown
            size={16}
            aria-hidden="true"
            className="shrink-0 text-muted-foreground"
          />
        </>
      )}
    </PressButton>
  );
}

export function SelectValue({
  className,
  ...props
}: React.ComponentProps<typeof AriaSelectValue>) {
  return (
    <AriaSelectValue
      {...props}
      data-slot="select-value"
      className={composeRenderProps(className, (className) =>
        cn(
          "min-w-0 flex-1 truncate text-start data-[placeholder]:text-muted-foreground",
          className,
        ),
      )}
    >
      {props.children ??
        (({ selectedText, defaultChildren }) =>
          selectedText || defaultChildren)}
    </AriaSelectValue>
  );
}

export function SelectContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  return (
    <Popover
      {...props}
      data-slot="select-content"
      placement={props.placement ?? "bottom start"}
      offset={props.offset ?? 7}
      className={composeRenderProps(className, (className) =>
        cn(
          "w-[var(--trigger-width)] rounded-lg border-0 p-1.5 ring-1 ring-border/70",
          className,
        ),
      )}
    >
      <ListBox
        data-slot="select-list-box"
        className="grid max-h-64 gap-1 overflow-y-auto outline-none"
      >
        {children}
      </ListBox>
    </Popover>
  );
}

export function SelectItem({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<typeof ListBoxItem>, "children"> & {
  children: ReactNode;
}) {
  return (
    <ListBoxItem
      {...props}
      data-slot="select-item"
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm outline-none hover:bg-muted data-[focused]:bg-muted data-[selected]:bg-accent data-[selected]:text-accent-foreground data-[focus-visible]:-outline-offset-2 data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring data-[disabled]:cursor-default data-[disabled]:opacity-50",
          className,
        ),
      )}
    >
      {children}
      <Check
        size={15}
        aria-hidden="true"
        className="ms-auto shrink-0 opacity-0 group-data-[selected]/item:opacity-100"
      />
    </ListBoxItem>
  );
}

export function SelectError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="select-error"
      className={cn("text-xs leading-5 text-destructive", className)}
    />
  );
}

export function SelectDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="select-description"
      className={cn("text-xs leading-5 text-muted-foreground", className)}
    />
  );
}
